        if (i == MAX_MON_MOVES)
            gAIScriptPtr += 7;
        else
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 3);
        break;
    }

Cmd_if_doesnt_have_move_with_effect.body:
s32 i;

    switch (gAIScriptPtr[1])
    {
    case AI_USER:
    case AI_USER_PARTNER:
        for (i = 0; i < MAX_MON_MOVES; i++)
        {
            if(gBattleMons[sBattler_AI].moves[i] != 0 && gBattleMoves[gBattleMons[sBattler_AI].moves[i]].effect == gAIScriptPtr[2])
                break;
        }
        if (i != MAX_MON_MOVES)
            gAIScriptPtr += 7;
        else
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 3);
        break;
    case AI_TARGET:
    case AI_TARGET_PARTNER:
        for (i = 0; i < MAX_MON_MOVES; i++)
        {
            if (BATTLE_HISTORY->usedMoves[gBattlerTarget].moves[i] && gBattleMoves[BATTLE_HISTORY->usedMoves[gBattlerTarget].moves[i]].effect == gAIScriptPtr[2])
                break;
        }
        if (i != MAX_MON_MOVES)
            gAIScriptPtr += 7;
        else
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 3);
        break;
    }

Cmd_if_any_move_disabled_or_encored.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    if (gAIScriptPtr[2] == 0)
    {
        if (gDisableStructs[battler].disabledMove == MOVE_NONE)
            gAIScriptPtr += 7;
        else
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 3);
    }
    else if (gAIScriptPtr[2] != 1)
    {
        gAIScriptPtr += 7;
    }
    else
    {
        if (gDisableStructs[battler].encoredMove != MOVE_NONE)
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 3);
        else
            gAIScriptPtr += 7;
    }

Cmd_if_curr_move_disabled_or_encored.body:
switch (gAIScriptPtr[1])
    {
    case 0:
        if (gDisableStructs[gActiveBattler].disabledMove == AI_THINKING_STRUCT->moveConsidered)
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 2);
        else
            gAIScriptPtr += 6;
        break;
    case 1:
        if (gDisableStructs[gActiveBattler].encoredMove == AI_THINKING_STRUCT->moveConsidered)
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 2);
        else
            gAIScriptPtr += 6;
        break;
    default:
        gAIScriptPtr += 6;
        break;
    }

Cmd_if_random_safari_flee.body:
u8 safariFleeRate = gBattleStruct->safariEscapeFactor * 5;  

    if ((u8)(Random() % 100) < safariFleeRate)
        gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 1);
    else
        gAIScriptPtr += 5;

Cmd_get_hold_effect.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    if (gActiveBattler != battler)
        AI_THINKING_STRUCT->funcResult = GetItemHoldEffect(BATTLE_HISTORY->itemEffects[battler]);
    else
        AI_THINKING_STRUCT->funcResult = GetItemHoldEffect(gBattleMons[battler].item);

    gAIScriptPtr += 2;

Cmd_if_holds_item.body:
u8 battler = BattleAI_GetWantedBattler(gAIScriptPtr[1]);
    u16 item;
    u8 itemLo, itemHi;

    if ((battler & BIT_SIDE) == (sBattler_AI & BIT_SIDE))
        item = gBattleMons[battler].item;
    else
        item = BATTLE_HISTORY->itemEffects[battler];

    itemHi = gAIScriptPtr[2];
    itemLo = gAIScriptPtr[3];

#ifdef BUGFIX



    if (((itemHi << 8) | itemLo) == item)
#else
    if ((itemLo | itemHi) == item)
#endif
        gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 4);
    else
        gAIScriptPtr += 8;

Cmd_get_gender.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    AI_THINKING_STRUCT->funcResult = GetGenderFromSpeciesAndPersonality(gBattleMons[battler].species, gBattleMons[battler].personality);

    gAIScriptPtr += 2;

Cmd_is_first_turn_for.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    AI_THINKING_STRUCT->funcResult = gDisableStructs[battler].isFirstTurn;

    gAIScriptPtr += 2;

Cmd_get_stockpile_count.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    AI_THINKING_STRUCT->funcResult = gDisableStructs[battler].stockpileCounter;

    gAIScriptPtr += 2;

Cmd_get_used_held_item.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    AI_THINKING_STRUCT->funcResult = *(u8 *)&gBattleStruct->usedHeldItems[battler];

    gAIScriptPtr += 2;

Cmd_get_protect_count.body:
u8 battler;

    if (gAIScriptPtr[1] == AI_USER)
        battler = sBattler_AI;
    else
        battler = gBattlerTarget;

    AI_THINKING_STRUCT->funcResult = gDisableStructs[battler].protectUses;

    gAIScriptPtr += 2;

Cmd_if_level_cond.body:
switch (gAIScriptPtr[1])
    {
    case 0:  
        if (gBattleMons[sBattler_AI].level > gBattleMons[gBattlerTarget].level)
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 2);
        else
            gAIScriptPtr += 6;
        break;
    case 1:  
        if (gBattleMons[sBattler_AI].level < gBattleMons[gBattlerTarget].level)
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 2);
        else
            gAIScriptPtr += 6;
        break;
    case 2:  
        if (gBattleMons[sBattler_AI].level == gBattleMons[gBattlerTarget].level)
            gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 2);
        else
            gAIScriptPtr += 6;
        break;
    }

Cmd_if_target_is_ally.body:
if ((sBattler_AI & BIT_SIDE) == (gBattlerTarget & BIT_SIDE))
        gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 1);
    else
        gAIScriptPtr += 5;

Cmd_if_flash_fired.body:
u8 battler = BattleAI_GetWantedBattler(gAIScriptPtr[1]);

    if (gBattleResources->flags->flags[battler] & RESOURCE_FLAG_FLASH_FIRE)
        gAIScriptPtr = T1_READ_PTR(gAIScriptPtr + 2);
    else
        gAIScriptPtr += 6;

AIStackPop.body:
if (gBattleResources->AI_ScriptsStack->size != 0)
    {
        --gBattleResources->AI_ScriptsStack->size;
        gAIScriptPtr = gBattleResources->AI_ScriptsStack->ptr[gBattleResources->AI_ScriptsStack->size];
        return TRUE;
    }
    else
    {
        return FALSE;
    }
